args.CommandLine:
powershell -Command "
function Get-FolderSize(\$path) {
    if (Test-Path \$path) {
        try {
            \$size = (Get-ChildItem -Path \$path -Recurse -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
            return [math]::Round(\$size / 1GB, 2)
        } catch { return 0 }
    }
    return 0
}

Write-Host 'User Temp:' (Get-FolderSize 'C:\Users\lg\AppData\Local\Temp') 'GB'
Write-Host 'Windows Temp:' (Get-FolderSize 'C:\Windows\Temp') 'GB'
Write-Host 'SoftwareDistribution Download:' (Get-FolderSize 'C:\Windows\SoftwareDistribution\Download') 'GB'
Write-Host 'Recycle Bin:' (Get-FolderSize 'C:\$Recycle.Bin') 'GB'
Write-Host 'npm cache:' (Get-FolderSize 'C:\Users\lg\AppData\Local\npm-cache') 'GB'
Write-Host 'pip cache:' (Get-FolderSize 'C:\Users\lg\AppData\Local\pip\cache') 'GB'
Write-Host 'Gemini/Antigravity logs/cache:' (Get-FolderSize 'C:\Users\lg\.gemini') 'GB'
Write-Host 'Downloads Folder:' (Get-FolderSize 'C:\Users\lg\Downloads') 'GB'
"

args.CodeContent:
$folders = @(
    @{ Name = "User Temp"; Path = "$env:TEMP" },
    @{ Name = "Windows Temp"; Path = "C:\Windows\Temp" },
    @{ Name = "SoftwareDistribution Download"; Path = "C:\Windows\SoftwareDistribution\Download" },
    @{ Name = "npm Cache"; Path = "$env:APPDATA\npm-cache" },
    @{ Name = "pip Cache"; Path = "$env:LOCALAPPDATA\pip\cache" },
    @{ Name = "Downloads Folder"; Path = "C:\Users\lg\Downloads" },
    @{ Name = "Recycle Bin"; Path = "C:\`$Recycle.Bin" }
)

foreach ($f in $folders) {
    if (Test-Path $f.Path) {
        $size = (Get-ChildItem -Path $f.Path -Recurse -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        $gb = [math]::Round(($size / 1GB), 2)
        Write-Host "$($f.Name): $gb GB ($f.Path)"
    } else {
        Write-Host "$($f.Name): Not found ($f.Path)"
    }
}

# Check Hibernation File
if (Test-Path "C:\hiberfil.sys") {
    $hib = Get-Item "C:\hiberfil.sys" -Force -ErrorAction SilentlyContinue
    $hibGB = [math]::Round(($hib.Length / 1GB), 2)
    Write-Host "Hibernation File (hiberfil.sys): $hibGB GB"
} else {
    Write-Host "Hibernation File (hiberfil.sys): Disabled / Not found"
}

# Check Pagefile
if (Test-Path "C:\pagefile.sys") {
    $page = Get-Item "C:\pagefile.sys" -Force -ErrorAction SilentlyContinue
    $pageGB = [math]::Round(($page.Length / 1GB), 2)
    Write-Host "Pagefile (pagefile.sys): $pageGB GB"
} else {
    Write-Host "Pagefile (pagefile.sys): Not found"
}

# Check Top 10 largest folders under C:\Users\lg (max depth 2)
Write-Host "`nTop Users\lg subdirectories:"
Get-ChildItem -Path "C:\Users\lg" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $dirSize = (Get-ChildItem -Path $_.FullName -Recurse -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    [PSCustomObject]@{
        Name = $_.Name
        SizeGB = [math]::Round(($dirSize / 1GB), 2)
    }
} | Sort-Object SizeGB -Descending | Select-Object -First 15 | Format-Table -AutoSize

function Get-DirSize($path) {
    if (Test-Path $path) {
        $size = (Get-ChildItem -Path $path -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        return [math]::Round(($size / 1GB), 2)
    }
    return 0
}

Write-Host "=== Top Level C:\ Folders ==="
Get-ChildItem -Path "C:\" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $s = Get-DirSize $_.FullName
    Write-Host "$($_.Name) : $s GB"
}

Write-Host "`n=== AppData Subdirectories (C:\Users\lg\AppData) ==="
Get-ChildItem -Path "C:\Users\lg\AppData" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $s = Get-DirSize $_.FullName
    Write-Host "$($_.Name) : $s GB"
}

Write-Host "`n=== AppData\Local Subdirectories ==="
Get-ChildItem -Path "C:\Users\lg\AppData\Local" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $s = Get-DirSize $_.FullName
    Write-Host "$($_.Name) : $s GB"
}

Write-Host "`n=== AppData\Roaming Subdirectories ==="
Get-ChildItem -Path "C:\Users\lg\AppData\Roaming" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $s = Get-DirSize $_.FullName
    Write-Host "$($_.Name) : $s GB"
}

$pathsToScan = @(
    "C:\Program Files",
    "C:\Program Files (x86)",
    "C:\Windows",
    "C:\Users",
    "C:\ProgramData"
)

foreach ($p in $pathsToScan) {
    if (Test-Path $p) {
        Write-Host "`n=== Top Subdirectories of $p ==="
        Get-ChildItem -Path $p -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $dir = $_
            $size = 0
            try {
                $files = [System.IO.Directory]::EnumerateFiles($dir.FullName, "*", [System.IO.SearchOption]::AllDirectories)
                foreach ($f in $files) {
                    try {
                        $size += (New-Object System.IO.FileInfo($f)).Length
                    } catch {}
                }
            } catch {}
            $gb = [math]::Round(($size / 1GB), 2)
            if ($gb -gt 0.1) {
                Write-Host "$($dir.Name) : $gb GB"
            }
        }
    }
}

function Get-SizeInGB($targetPath) {
    if (Test-Path $targetPath) {
        $files = Get-ChildItem -Path $targetPath -Recurse -File -ErrorAction SilentlyContinue
        if ($files) {
            $sum = ($files | Measure-Object -Property Length -Sum).Sum
            return [math]::Round(($sum / 1GB), 2)
        }
    }
    return 0
}

$report = @()

$targets = @(
    @{ Name = "User Temp Folder"; Path = "$env:TEMP" },
    @{ Name = "Windows System Temp"; Path = "C:\Windows\Temp" },
    @{ Name = "Windows Update Downloads"; Path = "C:\Windows\SoftwareDistribution\Download" },
    @{ Name = "Recycle Bin"; Path = "C:\`$Recycle.Bin" },
    @{ Name = "User Crash Dumps"; Path = "$env:LOCALAPPDATA\CrashDumps" },
    @{ Name = "pip Cache"; Path = "$env:LOCALAPPDATA\pip\cache" },
    @{ Name = "npm Cache"; Path = "$env:APPDATA\npm-cache" },
    @{ Name = "npm Local Cache"; Path = "$env:LOCALAPPDATA\npm-cache" },
    @{ Name = "Google Chrome Cache"; Path = "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache" },
    @{ Name = "MS Edge Cache"; Path = "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache" },
    @{ Name = "Gemini/Antigravity Data"; Path = "C:\Users\lg\.gemini" },
    @{ Name = "User Downloads Folder"; Path = "C:\Users\lg\Downloads" }
)

foreach ($t in $targets) {
    $gb = Get-SizeInGB $t.Path
    $report += [PSCustomObject]@{
        Target = $t.Name
        SizeGB = $gb
        Path   = $t.Path
    }
}

$report | Format-Table -AutoSize

Write-Host "=== Starting SSD Capacity Optimization ==="

# 1. Clean User Temp
Write-Host "`n[1/7] Cleaning User Temp Folder..."
try {
    Get-ChildItem -Path "$env:TEMP" -Recurse -ErrorAction SilentlyContinue | Where-Object { 
        !$_.PSIsContainer -and $_.Extension -ne ".xlsx" -and $_.Extension -ne ".xls" -and $_.Extension -ne ".xlsm" 
    } | Remove-Item -Force -ErrorAction SilentlyContinue
    Write-Host "User Temp cleaned."
} catch {
    Write-Host "User Temp partial clean."
}

# 2. Clean Windows System Temp
Write-Host "`n[2/7] Cleaning Windows System Temp..."
try {
    Get-ChildItem -Path "C:\Windows\Temp" -Recurse -ErrorAction SilentlyContinue | Where-Object {
        !$_.PSIsContainer -and $_.Extension -ne ".xlsx" -and $_.Extension -ne ".xls"
    } | Remove-Item -Force -ErrorAction SilentlyContinue
    Write-Host "Windows Temp cleaned."
} catch {
    Write-Host "Windows Temp partial clean."
}

# 3. Clean npm & pip Caches
Write-Host "`n[3/7] Cleaning npm and pip caches..."
if (Test-Path "$env:LOCALAPPDATA\npm-cache") {
    Remove-Item -Path "$env:LOCALAPPDATA\npm-cache\*" -Recurse -Force -ErrorAction SilentlyContinue
}
if (Test-Path "$env:APPDATA\npm-cache") {
    Remove-Item -Path "$env:APPDATA\npm-cache\*" -Recurse -Force -ErrorAction SilentlyContinue
}
try {
    python -m pip cache purge 2>$null
} catch {}

# 4. Clean Windows Update Download Cache
Write-Host "`n[4/7] Cleaning Windows Update Download Cache..."
if (Test-Path "C:\Windows\SoftwareDistribution\Download") {
    Remove-Item -Path "C:\Windows\SoftwareDistribution\Download\*" -Recurse -Force -ErrorAction SilentlyContinue
}

# 5. Clean Crash Dumps
Write-Host "`n[5/7] Cleaning User Crash Dumps..."
if (Test-Path "$env:LOCALAPPDATA\CrashDumps") {
    Remove-Item -Path "$env:LOCALAPPDATA\CrashDumps\*" -Recurse -Force -ErrorAction SilentlyContinue
}

# 6. Clear Recycle Bin
Write-Host "`n[6/7] Clearing Recycle Bin..."
try {
    Clear-RecycleBin -Force -ErrorAction SilentlyContinue
} catch {}

# 7. DISM Windows Component Cleanup (WinSxS)
Write-Host "`n[7/7] Running DISM StartComponentCleanup..."
try {
    Dism.exe /Online /Cleanup-Image /StartComponentCleanup
} catch {
    Write-Host "DISM cleanup require admin elevation or encountered notice."
}

Write-Host "`n=== SSD Optimization Completed ==="

$report = @()

# 1. Drive space
$vol = Get-Volume C
$freeGB = [math]::Round(($vol.SizeRemaining / 1GB), 2)
$totalGB = [math]::Round(($vol.Size / 1GB), 2)
Write-Host "Current C Drive Free: $freeGB GB / Total: $totalGB GB"

# 2. Hiberfil.sys check
if (Test-Path "C:\hiberfil.sys") {
    $item = Get-Item "C:\hiberfil.sys" -Force -ErrorAction SilentlyContinue
    $hSize = [math]::Round(($item.Length / 1GB), 2)
    Write-Host "hiberfil.sys exists: $hSize GB"
} else {
    Write-Host "hiberfil.sys: Not active / Not found"
}

# 3. Compact OS query
$compactQuery = compact.exe /CompactOS:query
Write-Host "`nCompactOS Status:"
Write-Host $compactQuery

# 4. Large folders in C:\Users\lg
Write-Host "`nScanning top folders in C:\Users\lg..."
Get-ChildItem -Path "C:\Users\lg" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $dirName = $_.Name
    $dirPath = $_.FullName
    $files = Get-ChildItem -Path $dirPath -Recurse -File -ErrorAction SilentlyContinue
    if ($files) {
        $sum = ($files | Measure-Object -Property Length -Sum).Sum
        $gb = [math]::Round(($sum / 1GB), 2)
        if ($gb -gt 0.3) {
            Write-Host "$dirName : $gb GB"
        }
    }
}

# 5. Check Chrome and Edge Cache sizes
$chromeCache = "$env:LOCALAPPDATA\Google\Chrome\User Data"
if (Test-Path $chromeCache) {
    $cFiles = Get-ChildItem -Path $chromeCache -Recurse -File -ErrorAction SilentlyContinue
    if ($cFiles) {
        $cSum = ($cFiles | Measure-Object -Property Length -Sum).Sum
        Write-Host "Chrome User Data: $([math]::Round(($cSum/1GB), 2)) GB"
    }
}

Write-Host "=== Starting Advanced SSD Capacity Optimization Phase 2 ==="

# 1. Windows Prefetch & Logs Cleanup
Write-Host "`n[1/6] Cleaning Windows Logs and Prefetch..."
try {
    Get-ChildItem -Path "C:\Windows\Logs" -Recurse -File -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
    Get-ChildItem -Path "C:\Windows\Prefetch" -Recurse -File -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
    Write-Host "Windows Logs & Prefetch cleaned."
} catch {
    Write-Host "Logs/Prefetch partial clean."
}

# 2. Browser Caches (Chrome / Edge / Brave / Firefox)
Write-Host "`n[2/6] Cleaning Web Browser Caches..."
$browserCachePaths = @(
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Code Cache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\GPUCache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Code Cache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\GPUCache"
)

foreach ($path in $browserCachePaths) {
    if (Test-Path $path) {
        Remove-Item -Path "$path\*" -Recurse -Force -ErrorAction SilentlyContinue
        Write-Host "Cleaned: $path"
    }
}

# 3. Delivery Optimization & Windows SoftwareDistribution Caches
Write-Host "`n[3/6] Cleaning Delivery Optimization & Windows Update Cache..."
try {
    Delete-DeliveryOptimizationCache -ErrorAction SilentlyContinue
} catch {}
if (Test-Path "C:\Windows\SoftwareDistribution\Download") {
    Remove-Item -Path "C:\Windows\SoftwareDistribution\Download\*" -Recurse -Force -ErrorAction SilentlyContinue
}

# 4. DISM StartComponentCleanup ResetBase (Deep WinSxS Cleanup)
Write-Host "`n[4/6] Executing DISM WinSxS ResetBase Cleanup..."
try {
    Dism.exe /Online /Cleanup-Image /StartComponentCleanup /ResetBase
    Write-Host "DISM ResetBase completed."
} catch {
    Write-Host "DISM notice/failed."
}

# 5. Compact OS Compression
Write-Host "`n[5/6] Enabling Compact OS (Compressing Windows binaries)..."
try {
    compact.exe /CompactOS:always
    Write-Host "Compact OS process finished."
} catch {
    Write-Host "Compact OS notice."
}

# 6. Recycle Bin Final Sweep
Write-Host "`n[6/6] Final Recycle Bin Sweep..."
try {
    Clear-RecycleBin -Force -ErrorAction SilentlyContinue
} catch {}

Write-Host "`n=== Advanced SSD Optimization Phase 2 Finished ==="

Write-Host "=== Advanced Non-Interactive SSD Cleanup Phase 2 ==="

# 1. Chrome & Edge Deep Cache Cleanup
Write-Host "`n[1/6] Cleaning Chrome & Edge Deep Caches..."
$cacheTargets = @(
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Code Cache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\GPUCache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Service Worker\CacheStorage",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Service Worker\ScriptCache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Crashpad",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Code Cache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\GPUCache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Crashpad"
)

foreach ($target in $cacheTargets) {
    if (Test-Path $target) {
        Remove-Item -Path "$target\*" -Recurse -Force -ErrorAction SilentlyContinue
        Write-Host "Cleaned: $target"
    }
}

# 2. Windows Logs, Temp & Prefetch
Write-Host "`n[2/6] Cleaning Windows System Logs & Prefetch..."
if (Test-Path "C:\Windows\Logs") {
    Get-ChildItem -Path "C:\Windows\Logs" -Recurse -File -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
}
if (Test-Path "C:\Windows\Prefetch") {
    Get-ChildItem -Path "C:\Windows\Prefetch" -Recurse -File -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
}

# 3. Windows Update & Delivery Optimization Folder Cleanup
Write-Host "`n[3/6] Cleaning Windows Update & Delivery Optimization Folders..."
if (Test-Path "C:\Windows\SoftwareDistribution\Download") {
    Remove-Item -Path "C:\Windows\SoftwareDistribution\Download\*" -Recurse -Force -ErrorAction SilentlyContinue
}
$doPath = "C:\ProgramData\Microsoft\Windows\DeliveryOptimizationCache"
if (Test-Path $doPath) {
    Remove-Item -Path "$doPath\*" -Recurse -Force -ErrorAction SilentlyContinue
}

# 4. DISM ResetBase Component Cleanup
Write-Host "`n[4/6] Running DISM WinSxS ResetBase Cleanup..."
try {
    Dism.exe /Online /Cleanup-Image /StartComponentCleanup /ResetBase
    Write-Host "DISM ResetBase completed successfully."
} catch {
    Write-Host "DISM encountered an issue or required higher privilege."
}

# 5. Compact OS Compression
Write-Host "`n[5/6] Enabling Compact OS Binary Compression..."
try {
    compact.exe /CompactOS:always
    Write-Host "Compact OS compression completed."
} catch {
    Write-Host "Compact OS encountered an issue."
}

# 6. Final Recycle Bin Sweep & Volume Measure
Write-Host "`n[6/6] Emptying Recycle Bin & Measuring C: Drive..."
try {
    Clear-RecycleBin -Force -ErrorAction SilentlyContinue
} catch {}

$vol = Get-Volume C
$freeGB = [math]::Round(($vol.SizeRemaining / 1GB), 2)
$totalGB = [math]::Round(($vol.Size / 1GB), 2)
Write-Host "`n=========================================="
Write-Host "FINAL C DRIVE FREE SPACE: $freeGB GB / $totalGB GB"
Write-Host "=========================================="

function Scan-FolderDetails($path) {
    if (Test-Path $path) {
        Write-Host "`n--- Scanning: $path ---"
        Get-ChildItem -Path $path -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $dir = $_
            $files = Get-ChildItem -Path $dir.FullName -Recurse -File -ErrorAction SilentlyContinue
            if ($files) {
                $sum = ($files | Measure-Object -Property Length -Sum).Sum
                $gb = [math]::Round(($sum / 1GB), 2)
                if ($gb -gt 0.05) {
                    Write-Host "$($dir.Name) : $gb GB"
                }
            }
        }
    }
}

Scan-FolderDetails "C:\Users\lg\.gemini"
Scan-FolderDetails "C:\Users\lg\.vscode"
Scan-FolderDetails "C:\Users\lg\.grok"
Scan-FolderDetails "C:\Users\lg\.cache"
Scan-FolderDetails "C:\Users\lg\AppData\Local"

Write-Host "=== AppData\Local Big Folders ==="
Get-ChildItem -Path "C:\Users\lg\AppData\Local" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $dir = $_
    $files = Get-ChildItem -Path $dir.FullName -Recurse -File -ErrorAction SilentlyContinue
    if ($files) {
        $sum = ($files | Measure-Object -Property Length -Sum).Sum
        $gb = [math]::Round(($sum / 1GB), 2)
        if ($gb -gt 0.2) {
            Write-Host "$($dir.Name) : $gb GB"
        }
    }
}

Write-Host "`n=== AppData\Roaming Big Folders ==="
Get-ChildItem -Path "C:\Users\lg\AppData\Roaming" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $dir = $_
    $files = Get-ChildItem -Path $dir.FullName -Recurse -File -ErrorAction SilentlyContinue
    if ($files) {
        $sum = ($files | Measure-Object -Property Length -Sum).Sum
        $gb = [math]::Round(($sum / 1GB), 2)
        if ($gb -gt 0.2) {
            Write-Host "$($dir.Name) : $gb GB"
        }
    }
}

Write-Host "=== Scanning All Top Folders under C:\ ==="
Get-ChildItem -Path "C:\" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $dName = $_.Name
    $dPath = $_.FullName
    $files = Get-ChildItem -Path $dPath -Recurse -File -ErrorAction SilentlyContinue
    if ($files) {
        $sum = ($files | Measure-Object -Property Length -Sum).Sum
        $gb = [math]::Round(($sum / 1GB), 2)
        Write-Host "$dName : $gb GB"
    }
}

$dirs = Get-ChildItem -Path "C:\" -Directory -ErrorAction SilentlyContinue

foreach ($d in $dirs) {
    try {
        $fList = [System.IO.Directory]::GetFiles($d.FullName, "*.*", [System.IO.SearchOption]::AllDirectories)
        $length = 0
        foreach ($f in $fList) {
            try {
                $length += (New-Object System.IO.FileInfo($f)).Length
            } catch {}
        }
        $gb = [math]::Round(($length / 1GB), 2)
        Write-Host "$($d.Name) : $gb GB"
    } catch {
        Write-Host "$($d.Name) : Access Denied or Skip"
    }
}

$vol = Get-Volume C
$freeGB = [math]::Round(($vol.SizeRemaining / 1GB), 2)
$totalGB = [math]::Round(($vol.Size / 1GB), 2)
Write-Host "Current C Drive Free: $freeGB GB / Total: $totalGB GB"

$targets = @(
    @{ Name = "User Temp"; Path = "$env:TEMP" },
    @{ Name = "System Temp"; Path = "C:\Windows\Temp" },
    @{ Name = "Windows Update Download"; Path = "C:\Windows\SoftwareDistribution\Download" },
    @{ Name = "Recycle Bin"; Path = "C:\`$Recycle.Bin" },
    @{ Name = "User CrashDumps"; Path = "$env:LOCALAPPDATA\CrashDumps" },
    @{ Name = "Chrome Cache"; Path = "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache" },
    @{ Name = "Chrome Code Cache"; Path = "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Code Cache" },
    @{ Name = "Edge Cache"; Path = "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache" },
    @{ Name = "pip cache"; Path = "$env:LOCALAPPDATA\pip\cache" },
    @{ Name = "npm cache"; Path = "$env:LOCALAPPDATA\npm-cache" },
    @{ Name = "Cursor Cache"; Path = "$env:APPDATA\Cursor\Cache" },
    @{ Name = "VSCode Cache"; Path = "$env:APPDATA\Code\Cache" },
    @{ Name = "Antigravity Cache"; Path = "C:\Users\lg\.gemini\antigravity\brain" }
)

foreach ($t in $targets) {
    if (Test-Path $t.Path) {
        $files = Get-ChildItem -Path $t.Path -Recurse -File -ErrorAction SilentlyContinue
        if ($files) {
            $sum = ($files | Measure-Object -Property Length -Sum).Sum
            $gb = [math]::Round(($sum / 1GB), 2)
            Write-Host "$($t.Name) : $gb GB"
        } else {
            Write-Host "$($t.Name) : 0 GB"
        }
    } else {
        Write-Host "$($t.Name) : Not Found"
    }
}

Write-Host "=== SSD Capacity Maximum Cleanup Started ==="

# 1. Measure initial space
$volBefore = Get-Volume C
$freeBefore = [math]::Round(($volBefore.SizeRemaining / 1GB), 2)
$totalGB = [math]::Round(($volBefore.Size / 1GB), 2)
Write-Host "Initial C: Free Space: $freeBefore GB / $totalGB GB"

# 2. Clean User Temp and Windows Temp (Exclude Excel)
Write-Host "`n[1/7] Cleaning Temp folders..."
Get-ChildItem -Path "$env:TEMP" -Recurse -File -ErrorAction SilentlyContinue | Where-Object { 
    $_.Extension -notmatch "^\.xl" 
} | Remove-Item -Force -ErrorAction SilentlyContinue

Get-ChildItem -Path "C:\Windows\Temp" -Recurse -File -ErrorAction SilentlyContinue | Where-Object { 
    $_.Extension -notmatch "^\.xl" 
} | Remove-Item -Force -ErrorAction SilentlyContinue

# 3. Clean Browser Deep Caches (Chrome & Edge)
Write-Host "`n[2/7] Cleaning Browser Caches..."
$browserCaches = @(
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Code Cache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\GPUCache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Service Worker\CacheStorage",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Service Worker\ScriptCache",
    "$env:LOCALAPPDATA\Google\Chrome\User Data\Crashpad",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Code Cache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\GPUCache",
    "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Crashpad"
)

foreach ($c in $browserCaches) {
    if (Test-Path $c) {
        Remove-Item -Path "$c\*" -Recurse -Force -ErrorAction SilentlyContinue
        Write-Host "Cleaned: $c"
    }
}

# 4. Clean Cursor & VS Code Editor Caches
Write-Host "`n[3/7] Cleaning Editor Caches (Cursor & VS Code)..."
$editorCaches = @(
    "$env:APPDATA\Cursor\Cache",
    "$env:APPDATA\Cursor\CachedData",
    "$env:APPDATA\Cursor\GPUCache",
    "$env:APPDATA\Cursor\logs",
    "$env:APPDATA\Cursor\Crashpad",
    "$env:APPDATA\Cursor\Service Worker\CacheStorage",
    "$env:APPDATA\Cursor\Service Worker\ScriptCache",
    "$env:APPDATA\Code\Cache",
    "$env:APPDATA\Code\CachedData",
    "$env:APPDATA\Code\GPUCache",
    "$env:APPDATA\Code\logs",
    "$env:APPDATA\Code\Crashpad",
    "$env:APPDATA\Code\Service Worker\CacheStorage",
    "$env:APPDATA\Code\Service Worker\ScriptCache"
)

foreach ($ec in $editorCaches) {
    if (Test-Path $ec) {
        Remove-Item -Path "$ec\*" -Recurse -Force -ErrorAction SilentlyContinue
        Write-Host "Cleaned editor cache: $ec"
    }
}

